class Solution:
 def largestGoodInteger(self, num):
  best = ""
  for i in range(len(num)-2):
   if num[i] == num[i+1] == num[i+2] and num[i] > best[:1]: best = num[i:i+3]
  return best

class Solution:
 def averageOfSubtree(self, root):
  self.ans = 0
  def dfs(node):
   if not node: return (0,0)
   ls,lc=dfs(node.left); rs,rc=dfs(node.right)
   total,count=ls+rs+node.val,lc+rc+1
   if total//count==node.val: self.ans+=1
   return total,count
  dfs(root); return self.ans

class Solution:
 def removeAnagrams(self, words):
  out=[]; prev=None
  for word in words:
   sig=''.join(sorted(word))
   if sig!=prev: out.append(word)
   prev=sig
  return out

class Solution:
 def digitCount(self, num):
  freq=[0]*10
  for ch in num: freq[int(ch)]+=1
  return all(freq[i]==int(ch) for i,ch in enumerate(num))

from collections import Counter
class Solution:
 def rearrangeCharacters(self,s,target):
  have,need=Counter(s),Counter(target)
  return min(have[c]//n for c,n in need.items())

class Solution:
 def discountPrices(self, sentence, discount):
  out=[]
  for t in sentence.split(' '):
   if len(t)>1 and t[0]=='$' and t[1:].isdigit(): out.append(f"${int(t[1:])*(100-discount)/100:.2f}")
   else: out.append(t)
  return ' '.join(out)

class Solution:
 def minMaxGame(self, nums):
  a=nums[:]
  while len(a)>1: a=[min(a[2*i],a[2*i+1]) if i%2==0 else max(a[2*i],a[2*i+1]) for i in range(len(a)//2)]
  return a[0]

class Solution:
 def calculateTax(self, brackets, income):
  tax=0.0; prev=0
  for upper,rate in brackets:
   taxable=min(income,upper)-prev
   if taxable>0: tax+=taxable*rate/100
   prev=upper
   if income<=upper: break
  return tax

class Solution:
